function materialTitle(text:string|undefined,fallback:string){
 const body=trustTextBody(text??'null');
 return [body?.title,body?.summary,body?.description,body?.strategy,body?.approach,body?.observation].find((value):value is string=>typeof value==='string'&&!!value.trim())??fallback;
}

const sourceName=(kind:string)=>({'case-event':'工作记录',evidence:'证据',verification:'验证记录',proof:'检查证明','ci-proof-v2':'自动检查证明'} as Record<string,string>)[kind]??'工作材料';
